-- GERADO por scripts/gerar-postcheck-109.mjs a partir de lib/assinatura/renovacao-schema.ts. Não editar à mão.
-- Somente leitura: o retrato completo de assinatura_renovacoes tem de ser IGUAL ao aprovado para a 109.
BEGIN TRANSACTION READ ONLY;
DO $$
DECLARE lido jsonb;
BEGIN
  PERFORM set_config('search_path', 'pg_catalog, pg_temp', true);
  WITH t AS (SELECT to_regclass('public.assinatura_renovacoes') AS rel),
  colunas AS (
    SELECT jsonb_agg(jsonb_build_object('nome', a.attname, 'tipo', format_type(a.atttypid, a.atttypmod), 'notnull', a.attnotnull,
        'default', pg_get_expr(d.adbin, d.adrelid)) ORDER BY a.attname) AS v
    FROM pg_attribute a CROSS JOIN t LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
    WHERE a.attrelid = t.rel AND a.attnum > 0 AND NOT a.attisdropped),
  constraints AS (
    SELECT jsonb_agg(jsonb_build_object('nome', c.conname, 'tipo', c.contype, 'def', pg_get_constraintdef(c.oid), 'validada', c.convalidated,
        'deferivel', c.condeferrable, 'diferida', c.condeferred) ORDER BY c.conname) AS v
    FROM pg_constraint c CROSS JOIN t WHERE c.conrelid = t.rel AND c.contype <> 't'),
  indices AS (
    SELECT jsonb_agg(jsonb_build_object('nome', ci.relname, 'def', pg_get_indexdef(i.indexrelid), 'unico', i.indisunique, 'valido', i.indisvalid,
        'pronto', i.indisready) ORDER BY ci.relname) AS v
    FROM pg_index i CROSS JOIN t JOIN pg_class ci ON ci.oid = i.indexrelid WHERE i.indrelid = t.rel),
  gatilhos AS (
    SELECT jsonb_agg(jsonb_build_object('nome', g.tgname, 'def', pg_get_triggerdef(g.oid), 'habilitado', g.tgenabled::text,
        'semWhen', g.tgqual IS NULL, 'semUpdateOf', g.tgattr::text = '', 'funcao', fn.nspname || '.' || f.proname,
        'constraint', cc.conname, 'deferivel', g.tgdeferrable, 'diferido', g.tginitdeferred) ORDER BY g.tgname) AS v
    FROM pg_trigger g CROSS JOIN t JOIN pg_proc f ON f.oid = g.tgfoid JOIN pg_namespace fn ON fn.oid = f.pronamespace
    LEFT JOIN pg_constraint cc ON cc.oid = g.tgconstraint
    WHERE g.tgrelid = t.rel AND NOT g.tgisinternal),
  funcoes AS (
    SELECT jsonb_agg(jsonb_build_object('nome', x.nome, 'corpo', x.corpo, 'secdef', x.secdef, 'config', x.config) ORDER BY x.nome) AS v
    FROM (SELECT DISTINCT fn.nspname || '.' || f.proname AS nome,
        encode(sha256(convert_to(replace(f.prosrc, E'\r\n', E'\n'), 'UTF8')), 'hex') AS corpo, f.prosecdef AS secdef,
        coalesce(array_to_string(f.proconfig, ';'), '') AS config
      FROM pg_trigger g CROSS JOIN t JOIN pg_proc f ON f.oid = g.tgfoid JOIN pg_namespace fn ON fn.oid = f.pronamespace
      WHERE g.tgrelid = t.rel AND NOT g.tgisinternal) x)
  SELECT CASE WHEN to_regclass('public.assinatura_renovacoes') IS NULL THEN NULL ELSE jsonb_build_object(
    'colunas', coalesce((SELECT v FROM colunas), '[]'), 'constraints', coalesce((SELECT v FROM constraints), '[]'),
    'indices', coalesce((SELECT v FROM indices), '[]'), 'gatilhos', coalesce((SELECT v FROM gatilhos), '[]'),
    'funcoes', coalesce((SELECT v FROM funcoes), '[]')) END AS retrato INTO lido;
  IF lido IS DISTINCT FROM '{"colunas":[{"default":"clock_timestamp()","nome":"atualizado_em","notnull":true,"tipo":"timestamp with time zone"},{"default":"30","nome":"aviso_dias","notnull":true,"tipo":"smallint"},{"default":null,"nome":"aviso_enviado_em","notnull":false,"tipo":"timestamp with time zone"},{"default":null,"nome":"aviso_id_externo","notnull":false,"tipo":"text"},{"default":null,"nome":"aviso_tentado_em","notnull":false,"tipo":"timestamp with time zone"},{"default":null,"nome":"contratacao_id","notnull":true,"tipo":"uuid"},{"default":"clock_timestamp()","nome":"criado_em","notnull":true,"tipo":"timestamp with time zone"},{"default":null,"nome":"destinatario_id","notnull":true,"tipo":"uuid"},{"default":null,"nome":"empresa_id","notnull":true,"tipo":"uuid"},{"default":"''PENDENTE''::text","nome":"estado","notnull":true,"tipo":"text"},{"default":"public.gen_random_uuid()","nome":"id","notnull":true,"tipo":"uuid"},{"default":null,"nome":"mensagem","notnull":true,"tipo":"jsonb"},{"default":null,"nome":"preco_aplicado_em","notnull":false,"tipo":"timestamp with time zone"},{"default":null,"nome":"primeira_data_regular","notnull":true,"tipo":"date"},{"default":null,"nome":"primeiro_vencimento","notnull":true,"tipo":"date"},{"default":null,"nome":"substitui_id","notnull":false,"tipo":"uuid"},{"default":null,"nome":"ultimo_erro","notnull":false,"tipo":"text"}],"constraints":[{"def":"UNIQUE (empresa_id, contratacao_id, id)","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_109_cadeia_alvo_uq","tipo":"u","validada":true},{"def":"FOREIGN KEY (empresa_id, contratacao_id, substitui_id) REFERENCES public.assinatura_renovacoes(empresa_id, contratacao_id, id)","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_109_cadeia_fk","tipo":"f","validada":true},{"def":"CHECK ((estado = ANY (ARRAY[''PENDENTE''::text, ''AVISANDO''::text, ''AVISADA''::text, ''APLICANDO''::text, ''REGULAR''::text, ''REVISAO''::text, ''CANCELADA''::text, ''SUBSTITUIDA''::text])))","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_109_estado_check","tipo":"c","validada":true},{"def":"UNIQUE (substitui_id)","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_109_substitui_uq","tipo":"u","validada":true},{"def":"CHECK (((estado <> ''SUBSTITUIDA''::text) OR ((aviso_tentado_em IS NULL) AND (aviso_enviado_em IS NULL) AND (aviso_id_externo IS NULL) AND (preco_aplicado_em IS NULL))))","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_109_substituida_sem_evidencia","tipo":"c","validada":true},{"def":"NOT NULL atualizado_em","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_atualizado_em_not_null","tipo":"n","validada":true},{"def":"CHECK ((aviso_dias = 30))","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_aviso_dias_check","tipo":"c","validada":true},{"def":"NOT NULL aviso_dias","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_aviso_dias_not_null","tipo":"n","validada":true},{"def":"CHECK ((primeira_data_regular > primeiro_vencimento))","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_check","tipo":"c","validada":true},{"def":"CHECK (((jsonb_typeof(mensagem) = ''object''::text) AND (mensagem ?& ARRAY[''para''::text, ''assunto''::text, ''texto''::text, ''html''::text, ''idempotencia''::text]) AND (jsonb_typeof((mensagem -> ''para''::text)) = ''string''::text) AND (jsonb_typeof((mensagem -> ''texto''::text)) = ''string''::text) AND ((mensagem ->> ''idempotencia''::text) = (''kidmais-renovacao/''::text || (id)::text))))","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_check1","tipo":"c","validada":true},{"def":"CHECK (((aviso_enviado_em IS NULL) OR ((aviso_tentado_em IS NOT NULL) AND (aviso_enviado_em >= aviso_tentado_em) AND (aviso_id_externo IS NOT NULL))))","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_check2","tipo":"c","validada":true},{"def":"CHECK (((aviso_enviado_em IS NULL) OR (((aviso_enviado_em AT TIME ZONE ''America/Sao_Paulo''::text))::date <= (primeira_data_regular - (aviso_dias)::integer))))","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_check3","tipo":"c","validada":true},{"def":"CHECK (((estado <> ALL (ARRAY[''AVISADA''::text, ''APLICANDO''::text, ''REGULAR''::text])) OR (aviso_enviado_em IS NOT NULL)))","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_check4","tipo":"c","validada":true},{"def":"CHECK (((estado <> ''REGULAR''::text) OR (preco_aplicado_em IS NOT NULL)))","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_check5","tipo":"c","validada":true},{"def":"CHECK (((preco_aplicado_em IS NULL) OR ((aviso_enviado_em IS NOT NULL) AND (preco_aplicado_em >= aviso_enviado_em))))","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_check6","tipo":"c","validada":true},{"def":"NOT NULL contratacao_id","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_contratacao_id_not_null","tipo":"n","validada":true},{"def":"NOT NULL criado_em","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_criado_em_not_null","tipo":"n","validada":true},{"def":"FOREIGN KEY (destinatario_id) REFERENCES public.usuarios_administrativos(id)","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_destinatario_id_fkey","tipo":"f","validada":true},{"def":"NOT NULL destinatario_id","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_destinatario_id_not_null","tipo":"n","validada":true},{"def":"FOREIGN KEY (empresa_id, contratacao_id) REFERENCES public.assinatura_contratacoes(empresa_id, id)","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_empresa_id_contratacao_id_fkey","tipo":"f","validada":true},{"def":"FOREIGN KEY (empresa_id) REFERENCES public.empresas(id)","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_empresa_id_fkey","tipo":"f","validada":true},{"def":"NOT NULL empresa_id","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_empresa_id_not_null","tipo":"n","validada":true},{"def":"NOT NULL estado","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_estado_not_null","tipo":"n","validada":true},{"def":"NOT NULL id","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_id_not_null","tipo":"n","validada":true},{"def":"NOT NULL mensagem","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_mensagem_not_null","tipo":"n","validada":true},{"def":"PRIMARY KEY (id)","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_pkey","tipo":"p","validada":true},{"def":"NOT NULL primeira_data_regular","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_primeira_data_regular_not_null","tipo":"n","validada":true},{"def":"NOT NULL primeiro_vencimento","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_primeiro_vencimento_not_null","tipo":"n","validada":true},{"def":"CHECK (((ultimo_erro IS NULL) OR (ultimo_erro ~ ''^[A-Z0-9_]{1,80}$''::text)))","deferivel":false,"diferida":false,"nome":"assinatura_renovacoes_ultimo_erro_check","tipo":"c","validada":true}],"funcoes":[{"config":"search_path=pg_catalog, pg_temp","corpo":"2b8847b30d352797e7a7146c5d81fec73ad536553392668a226b609782e3ef32","nome":"public.kidmais_109_renovacao_guarda","secdef":false},{"config":"search_path=pg_catalog, pg_temp","corpo":"96bae8fe138c320fb7741d80f5b218100565ec747fee00864588fa7ad262a76d","nome":"public.kidmais_109_renovacao_sucessor","secdef":false}],"gatilhos":[{"constraint":null,"def":"CREATE TRIGGER assinatura_renovacoes_075_guarda BEFORE INSERT OR DELETE OR UPDATE ON public.assinatura_renovacoes FOR EACH ROW EXECUTE FUNCTION public.kidmais_109_renovacao_guarda()","deferivel":false,"diferido":false,"funcao":"public.kidmais_109_renovacao_guarda","habilitado":"O","nome":"assinatura_renovacoes_075_guarda","semUpdateOf":true,"semWhen":true},{"constraint":null,"def":"CREATE TRIGGER assinatura_renovacoes_075_truncate BEFORE TRUNCATE ON public.assinatura_renovacoes FOR EACH STATEMENT EXECUTE FUNCTION public.kidmais_109_renovacao_guarda()","deferivel":false,"diferido":false,"funcao":"public.kidmais_109_renovacao_guarda","habilitado":"O","nome":"assinatura_renovacoes_075_truncate","semUpdateOf":true,"semWhen":true},{"constraint":"assinatura_renovacoes_109_sucessor","def":"CREATE CONSTRAINT TRIGGER assinatura_renovacoes_109_sucessor AFTER UPDATE ON public.assinatura_renovacoes DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.kidmais_109_renovacao_sucessor()","deferivel":true,"diferido":true,"funcao":"public.kidmais_109_renovacao_sucessor","habilitado":"O","nome":"assinatura_renovacoes_109_sucessor","semUpdateOf":true,"semWhen":true}],"indices":[{"def":"CREATE UNIQUE INDEX assinatura_renovacoes_109_cadeia_alvo_uq ON public.assinatura_renovacoes USING btree (empresa_id, contratacao_id, id)","nome":"assinatura_renovacoes_109_cadeia_alvo_uq","pronto":true,"unico":true,"valido":true},{"def":"CREATE UNIQUE INDEX assinatura_renovacoes_109_substitui_uq ON public.assinatura_renovacoes USING btree (substitui_id)","nome":"assinatura_renovacoes_109_substitui_uq","pronto":true,"unico":true,"valido":true},{"def":"CREATE UNIQUE INDEX assinatura_renovacoes_109_vigente_uq ON public.assinatura_renovacoes USING btree (contratacao_id) WHERE (estado <> ''SUBSTITUIDA''::text)","nome":"assinatura_renovacoes_109_vigente_uq","pronto":true,"unico":true,"valido":true},{"def":"CREATE INDEX assinatura_renovacoes_pendentes_idx ON public.assinatura_renovacoes USING btree (estado, primeira_data_regular)","nome":"assinatura_renovacoes_pendentes_idx","pronto":true,"unico":false,"valido":true},{"def":"CREATE UNIQUE INDEX assinatura_renovacoes_pkey ON public.assinatura_renovacoes USING btree (id)","nome":"assinatura_renovacoes_pkey","pronto":true,"unico":true,"valido":true}]}'::jsonb THEN RAISE EXCEPTION '109 postcheck: retrato de assinatura_renovacoes diverge do aprovado'; END IF;
END $$;
ROLLBACK;
